import{readFile,readdir,mkdir,writeFile}from'node:fs/promises';import{join}from'node:path';import{gzipSync,brotliCompressSync}from'node:zlib';import{createHash}from'node:crypto';import{load}from'cheerio';import{chromium}from'playwright';
const root='site',out='diagnostics/seo-transform-baseline-20261122',report={sourceSha:process.env.SOURCE_SHA,capturedAt:new Date().toISOString(),scope:'Actual HTTP and source audit; lab performance, not CrUX or Google indexing/rank',pages:[],live:[],performance:[],issues:[],status:'PASS'};await mkdir(out,{recursive:true});const registry=JSON.parse(await readFile(join(root,'src/registry/published-services.json'),'utf8')),summary=JSON.parse(await readFile(join(root,'platform-summary.json'),'utf8'));const urls=[...((await readFile(join(root,'sitemap.xml'),'utf8')).matchAll(/<loc>([^<]+)<\/loc>/g))].map(m=>m[1].replaceAll('&amp;','&'));report.counts={sourceRecords:registry.services.length,authorities:new Set(registry.services.map(x=>x.authority.id)).size,detailsComplete:registry.services.filter(x=>x.verification.detailsVerified).length,summaryActivities:summary.activities,sitemapUrls:urls.length};const files=[];
async function walk(p){for(const e of await readdir(p,{withFileTypes:true})){if(e.name.startsWith('.')||['node_modules','artifacts','diagnostics','test','work'].includes(e.name))continue;const f=join(p,e.name);if(e.isDirectory())await walk(f);else if(e.name.endsWith('.html'))files.push(f);}}await walk(root);
for(const f of files){const html=await readFile(f,'utf8'),$=load(html);$('script,style,template').remove();const route='/'+f.slice(5).replaceAll('\\','/').replace(/index.html$/,''),canonical=$('link[rel=canonical]').attr('href'),noindex=/noindex/i.test($('meta[name=robots]').attr('content')||''),row={route,bytes:Buffer.byteLength(html),gzipBytes:gzipSync(html).length,brotliBytes:brotliCompressSync(html).length,title:$('title').text(),description:$('meta[name=description]').attr('content')||'',h1Count:$('h1').length,h2Count:$('h2').length,canonical,noindex,hreflang:$('link[hreflang]').map((i,e)=>$(e).attr('hreflang')).get(),wordCount:$('main').text().trim().split(/\s+/).length,images:$('img').length,missingAlt:$('img:not([alt])').length,internalLinks:$('a[href^="/"]').length,cardCount:$('[data-service-card],[data-directory-card],[data-service-slug],[data-canonical-service]').length};report.pages.push(row);if(urls.includes('https://hossambahr.com'+route)){if(noindex)report.issues.push({severity:'high',route,issue:'SITEMAP_NOINDEX'});if(!row.title||!row.description||row.h1Count!==1)report.issues.push({severity:'medium',route,issue:'META_OR_H1',h1Count:row.h1Count});if(row.missingAlt)report.issues.push({severity:'low',route,issue:'MISSING_ALT',count:row.missingAlt});if(route.startsWith('/categories/')&&!row.cardCount)report.issues.push({severity:'medium',route,issue:'EMPTY_CATEGORY_INDEXABLE'});}}
let index=0;await Promise.all(Array.from({length:6},async()=>{while(index<urls.length){const url=urls[index++];try{const start=Date.now(),r=await fetch(url,{redirect:'follow',signal:AbortSignal.timeout(30000)}),text=await r.text(),path=decodeURIComponent(new URL(url).pathname),local=await readFile(join(root,path==='/'?'index.html':path.slice(1),'index.html').replace('index.html/index.html','index.html'),'utf8'),hash=s=>createHash('sha256').update(s).digest('hex');report.live.push({url,status:r.status,finalUrl:r.url,responseMs:Date.now()-start,bytes:Buffer.byteLength(text),exactSourceBytes:hash(text)===hash(local),robotsHeader:r.headers.get('x-robots-tag')});}catch(e){report.live.push({url,error:e.message});}}}));
const browser=await chromium.launch({headless:true,executablePath:process.env.HB_BROWSER_PATH});try{for(const route of['/services/','/en/services/','/discover/','/business-activities/']){const page=await browser.newPage({viewport:{width:390,height:844}}),cdp=await page.context().newCDPSession(page);await cdp.send('Emulation.setCPUThrottlingRate',{rate:4});await cdp.send('Network.enable');await cdp.send('Network.emulateNetworkConditions',{offline:false,latency:150,downloadThroughput:200000,uploadThroughput:93750});await page.addInitScript(()=>{window.__lab={lcp:null,cls:0};new PerformanceObserver(l=>{for(const e of l.getEntries())window.__lab.lcp=e.startTime}).observe({type:'largest-contentful-paint',buffered:true});new PerformanceObserver(l=>{for(const e of l.getEntries())if(!e.hadRecentInput)window.__lab.cls+=e.value}).observe({type:'layout-shift',buffered:true});});await page.goto('https://hossambahr.com'+route,{waitUntil:'networkidle',timeout:90000});await page.waitForTimeout(1500);const metrics=await page.evaluate(()=>({lab:window.__lab,domNodes:document.querySelectorAll('*').length,overflow:document.documentElement.scrollWidth>innerWidth+2,navigation:performance.getEntriesByType('navigation').map(e=>({ttfb:e.responseStart,domContentLoaded:e.domContentLoadedEventEnd,encodedBodyBytes:e.encodedBodySize,decodedBodyBytes:e.decodedBodySize}))}));await page.screenshot({path:out+'/'+route.replaceAll('/','-')+'.jpg',type:'jpeg',quality:75});report.performance.push({route,viewport:390,cpuSlowdown:4,latencyMs:150,downloadBytesPerSecond:200000,...metrics});await page.close();}}finally{await browser.close();}
report.liveFailures=report.live.filter(x=>x.status!==200||!x.exactSourceBytes);report.status=report.liveFailures.length?'PARTIAL PASS':'PASS';await writeFile(out+'/report.json',JSON.stringify(report,null,2));console.log(JSON.stringify({status:report.status,counts:report.counts,pages:report.pages.length,live:report.live.length,liveFailures:report.liveFailures.length,issues:report.issues,performance:report.performance}));
